/**
 * Admin seeding tool for the Town Hall request notices (build plan M30, npc-runtime.md §9.3,
 * architecture §6.3). Only this tool writes the shared `cache/*`: it publishes one notice per
 * request template × target language × level band as
 * `cache/lines/{sha256(questNoticeSeedMaterial(templateId, lang, level))}`, with its translations
 * by native language. A template the file lacks is generated by the client for that player alone
 * (hybrid task `questNotice`, cloud first) and kept in the player's IndexedDB; without either the
 * board shows the request's quest card (world labels).
 *
 *   npm run seed:quests -- --prompts <lang> <A1|B1|C1> [<nativeLang>]   print the generation prompts
 *   npm run seed:quests -- <notices.json>                              dry run: validate, list gaps
 *   npm run seed:quests -- <notices.json> --write --project <id>       publish (admin credentials)
 *
 * The notices file: `{ "lang": "es", "level": "A1", "notices": { "<templateId>": { "text", "reading"?,
 * "translation": { "en": "…" } } } }`, where `text` (and `reading` and each translation) holds the
 * title and then the body lines, one per line (shared `noticeToCachedLine`). Run the printed
 * prompts through the cloud model (`gemini-3.8-flash`) with the `questNotice` JSON schema and
 * spot-check each notice before writing.
 *
 * TODO(seeding tool, no milestone yet, see pending.md): run the prompts from here with the admin
 * project, and voice the notices (seeded `tts/` clips).
 */
import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
import { z } from "zod";
import {
  BAND_LEVEL,
  type CachedLine,
  CachedLineSchema,
  FirestorePaths,
  getLanguage,
  getQuestTemplate,
  type Level,
  levelBand,
  noticeFromCachedLine,
  QUEST_NOTICE_MAX_WORDS,
  QUEST_TEMPLATE_IDS,
  QUEST_TEMPLATES,
  questFacts,
  questNoticePrompt,
  questNoticeSeedMaterial,
} from "../../packages/shared/src/index";

const BAND_LEVELS = Object.values(BAND_LEVEL) as Level[];

export const NoticesFileSchema = z.strictObject({
  lang: z.string().min(2).max(20),
  level: z.enum(BAND_LEVELS as [Level, ...Level[]]),
  notices: z.record(z.string(), CachedLineSchema),
});

export interface NoticesPlan {
  lang: string;
  level: Level;
  docs: { templateId: string; path: string; doc: CachedLine }[];
  /** Templates the file does not cover (generated per player on a miss). */
  missing: string[];
}

export const sha256 = (text: string) => createHash("sha256").update(text).digest("hex");

export function planQuestSeed(raw: unknown): NoticesPlan {
  const file = NoticesFileSchema.parse(raw);
  if (!getLanguage(file.lang)) throw new Error(`unknown language: ${file.lang}`);
  const unknown = Object.keys(file.notices).filter((k) => !getQuestTemplate(k));
  if (unknown.length) throw new Error(`unknown request templates: ${unknown.join(", ")}`);
  const broken = Object.entries(file.notices).filter(([, doc]) => !noticeFromCachedLine(doc, Object.keys(doc.translation ?? {})[0] ?? "en"));
  if (broken.length) throw new Error(`notices need a title and at least one body line: ${broken.map(([id]) => id).join(", ")}`);
  const docs = Object.entries(file.notices).map(([templateId, doc]) => ({
    templateId,
    path: FirestorePaths.cacheEntry("lines", sha256(questNoticeSeedMaterial(templateId, file.lang, file.level))),
    doc,
  }));
  return { lang: file.lang, level: file.level, docs, missing: QUEST_TEMPLATE_IDS.filter((id) => !Object.hasOwn(file.notices, id)) };
}

/** One prompt per request template, at a level band. */
export function questPrompts(lang: string, level: Level, nativeLang = "en"): { templateId: string; prompt: string }[] {
  if (!getLanguage(lang)) throw new Error(`unknown language: ${lang}`);
  if (!getLanguage(nativeLang)) throw new Error(`unknown language: ${nativeLang}`);
  if (!BAND_LEVELS.includes(level)) throw new Error(`level must be one of ${BAND_LEVELS.join(", ")}`);
  return QUEST_TEMPLATES.map((t) => ({
    templateId: t.id,
    prompt: questNoticePrompt({ targetLang: lang, nativeLang, level, maxWords: QUEST_NOTICE_MAX_WORDS[levelBand(level)], facts: { ...questFacts(t) } }),
  }));
}

export async function writeQuestSeed(plan: NoticesPlan, projectId: string): Promise<void> {
  const { initializeApp, applicationDefault } = await import("firebase-admin/app");
  const { getFirestore } = await import("firebase-admin/firestore");
  const emulated = Boolean(process.env.FIRESTORE_EMULATOR_HOST);
  const app = initializeApp(emulated ? { projectId } : { projectId, credential: applicationDefault() }, "hellovalley-seed-quests");
  const db = getFirestore(app);
  await Promise.all(plan.docs.map((d) => db.doc(d.path).set(d.doc)));
  console.log(`seeded ${plan.docs.length} request notices for ${plan.lang} at ${plan.level}`);
}

function arg(args: readonly string[], name: string): string | undefined {
  const i = args.indexOf(name);
  return i >= 0 ? args[i + 1] : undefined;
}

export async function main(args: readonly string[]): Promise<number> {
  const promptsFor = arg(args, "--prompts");
  if (promptsFor) {
    const at = args.indexOf("--prompts");
    const level = args[at + 2] as Level | undefined;
    const native = args[at + 3];
    if (!level || !BAND_LEVELS.includes(level)) {
      console.error(`usage: seed-quests --prompts <lang> <${BAND_LEVELS.join("|")}> [<nativeLang>]`);
      return 2;
    }
    for (const p of questPrompts(promptsFor, level, native && !native.startsWith("--") ? native : "en")) console.log(`--- ${p.templateId}\n${p.prompt}\n`);
    return 0;
  }
  const path = args[0];
  if (!path || path.startsWith("--")) {
    console.error("usage: seed-quests --prompts <lang> <A1|B1|C1> [<nativeLang>] | <notices.json> [--write --project <id>]");
    return 2;
  }
  const plan = planQuestSeed(JSON.parse(await readFile(path, "utf8")));
  console.log(`${plan.lang} ${plan.level}: ${plan.docs.length} notices, ${plan.missing.length} templates missing${plan.missing.length ? ` (${plan.missing.join(", ")})` : ""}`);
  if (!args.includes("--write")) {
    console.log("dry run: nothing written (add --write --project <id>)");
    return 0;
  }
  const projectId = arg(args, "--project");
  if (!projectId) {
    console.error("--write needs --project <id>");
    return 2;
  }
  if (!process.env.FIRESTORE_EMULATOR_HOST && !process.env.GOOGLE_APPLICATION_CREDENTIALS) {
    console.error("--write needs GOOGLE_APPLICATION_CREDENTIALS (an admin service account) or the emulators");
    return 2;
  }
  await writeQuestSeed(plan, projectId);
  return 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main(process.argv.slice(2)).then(
    (code) => process.exit(code),
    (error: unknown) => {
      console.error(error instanceof Error ? error.message : error);
      process.exit(1);
    },
  );
}
